def fetch_eia(series_id, start, end, *, budget, use_cache=True, api_key=None):
    key = api_key or os.environ.get("EIA_API_KEY", "")
    if not key:
        raise EnvironmentError("EIA_API_KEY is not set. ...")

    def _fetch():
        rows = []
        offset = 0
        page_size = 5000
        while True:
            params = urllib.parse.urlencode({
                "api_key": key, "start": start, "end": end,
                "sort[0][column]": "period", "sort[0][direction]": "asc",
                "offset": offset, "length": page_size,
            })
            url = f"https://api.eia.gov/v2/seriesid/{series_id}?{params}"
            with urllib.request.urlopen(url, timeout=30) as resp:
                payload = json.loads(resp.read().decode("utf-8"))
            data = payload.get("response", {}).get("data", [])
            if not data:
                break
            rows.extend(data)
            if len(data) < page_size:
                break
            offset += page_size

        df = pd.DataFrame(rows)
        df["value"] = pd.to_numeric(df["value"], errors="coerce")
        df = df[df["value"] > 0].copy()   # non-positive filter
        ...

    return _from_cache_or("eia", series_id, start, end, _fetch, budget=budget, source="eia", use_cache=use_cache)

def _from_cache_or(kind, symbol, start, end, fetch, *, budget, source, use_cache):
    if use_cache:
        cached = cache.load(kind, symbol, start, end)
        if cached is not None and not cached.empty:
            return cached        # cache hit: no charge
    df = fetch()                # network hit: fetch() calls budget.charge() inside _from_cache_or
    budget.charge(source)
    if use_cache and not df.empty:
        cache.save(df, kind, symbol, start, end)
    return df
```

