281	    <span class="kw">const</span> std::size_t n = values.size();
282	    std::vector&lt;<span class="ty">double</span>&gt; out(n, std::numeric_limits&lt;<span class="ty">double</span>&gt;::quiet_NaN());
283	    <span class="ty">double</span> sum = <span class="num">0.0</span>;
284	    <span class="kw">for</span> (std::size_t i = <span class="num">0</span>; i &lt; n; ++i) {
285	        sum += values[i];
286	        <span class="kw">if</span> (i &gt;= <span class="kw">static_cast</span>&lt;std::size_t&gt;(window)) sum -= values[i - window];
287	        <span class="kw">if</span> (i + <span class="num">1</span> &gt;= <span class="kw">static_cast</span>&lt;std::size_t&gt;(window)) out[i] = sum / window;
288	    }
289	    <span class="kw">return</span> out;
290	}
291	
292	<span class="cmt">// The module entry point.  Name must match the CMake target name.</span>
293	<span class="fn">PYBIND11_MODULE</span>(oil_volume_cpp, m) {
294	    m.doc() = <span class="str">"C++ core for oil-volume metrics (pybind11 bridge)"</span>;
295	    m.<span class="fn">def</span>(
296	        <span class="str">"rolling_mean"</span>,
297	        &amp;rolling_mean,               <span class="cmt">// pointer to C++ function</span>
298	        py::<span class="fn">arg</span>(<span class="str">"values"</span>),           <span class="cmt">// keyword arg name</span>
299	        py::<span class="fn">arg</span>(<span class="str">"window"</span>),
300	        <span class="str">"Compute a rolling arithmetic mean over *values* with the given *window*.\n"</span>
301	        <span class="str">"Returns a list of length len(values); the first window-1 entries are NaN."</span>
302	    );
303	}</pre>
304	
305	<p>Key structural observations:</p>
306	<ul>
307	  <li><strong>The C++ logic is completely separate from the binding layer.</strong> <code>rolling_mean</code> is a plain function you could unit-test in a standalone C++ executable. The <code>PYBIND11_MODULE</code> block is just a thin facade — this makes it easy to benchmark or fuzz the C++ side independently.</li>
308	  <li><strong><code>#include &lt;pybind11/stl.h&gt;</code> is required</strong> for the <code>std::vector</code> ↔ <code>list</code> conversion. Without it, the compiler will fail with a missing type caster error.</li>
309	  <li><strong>C++ exceptions propagate correctly.</strong> When <code>rolling_mean</code> throws <code>std::invalid_argument</code>, pybind11 catches it and re-raises it as a Python <code>ValueError</code> — tested by <code>test_rolling_mean_invalid_window</code>.</li>
310	</ul>
311	
312	<!-- ─────────────────────────────────────────────── -->
313	<h2 id="cmake-structure">4. CMake Structure: Root + Subdirectory</h2>
314	
315	<p>The project uses a two-level CMake layout. This is standard practice for multi-target C++ projects.</p>
316	
317	<div class="file-label">CMakeLists.txt (root)</div>
318	<pre><span class="fn">cmake_minimum_required</span>(VERSION <span class="num">3.21</span>)
319	<span class="fn">project</span>(oil_volume_cpp LANGUAGES CXX)
320	
321	<span class="fn">set</span>(CMAKE_CXX_STANDARD <span class="num">17</span>)
322	<span class="fn">set</span>(CMAKE_CXX_STANDARD_REQUIRED ON)
323	
324	<span class="fn">include</span>(FetchContent)
325	
326	<span class="cmt"># Tell pybind11 to use the modern FindPython3 module</span>
327	<span class="fn">set</span>(PYBIND11_FINDPYTHON ON)
328	
329	<span class="cmt"># Try pip-installed pybind11 first (fast, no network call)</span>
330	<span class="fn">find_package</span>(pybind11 CONFIG QUIET)
331	<span class="kw">if</span>(NOT pybind11_FOUND)
332	    <span class="fn">FetchContent_Declare</span>(
333	        pybind11
334	        GIT_REPOSITORY https://github.com/pybind/pybind11.git
335	        GIT_TAG        v2.13.6
336	    )
337	    <span class="fn">FetchContent_MakeAvailable</span>(pybind11)
338	<span class="kw">endif</span>()
339	
340	<span class="fn">add_subdirectory</span>(cpp/oil_volume)   <span class="cmt"># delegates to the module CMakeLists</span></pre>
341	
342	<div class="file-label">cpp/oil_volume/CMakeLists.txt</div>
343	<pre><span class="cmt"># pybind11_add_module wraps add_library() with Python-specific flags</span>
344	<span class="fn">pybind11_add_module</span>(oil_volume_cpp bindings.cpp)
345	<span class="fn">target_include_directories</span>(oil_volume_cpp PRIVATE ${CMAKE_CURRENT_SOURCE_DIR})</pre>
346	
347	<h3>What pybind11_add_module does</h3>
348	<p><code>pybind11_add_module</code> is a CMake function defined in pybind11's CMake support files. It is a wrapper around <code>add_library(... SHARED ...)</code> that automatically:</p>
349	<ul>
350	  <li>Sets the correct Python extension suffix (<code>.cpython-312-x86_64-linux-gnu.so</code>) via <code>set_target_properties(... SUFFIX ...)</code></li>
351	  <li>Strips the default <code>lib</code> prefix from the shared library name</li>
352	  <li>Links against Python's shared library (or just the headers for the stable ABI)</li>
353	  <li>Applies <code>-fvisibility=hidden</code> to avoid symbol collisions when multiple extensions are loaded in the same process</li>
354	  <li>Enables link-time optimisation (<code>-flto</code>) when building in Release mode</li>
355	</ul>
356	
357	<div class="callout warn">
358	  <strong>Name coupling</strong>
359	  The string you pass to <code>pybind11_add_module</code> (<code>oil_volume_cpp</code>), the string inside <code>PYBIND11_MODULE(oil_volume_cpp, m)</code> in your C++ code, and the Python import name (<code>import oil_volume_cpp</code>) must all be identical. A mismatch causes either a linker error or a Python <code>ImportError: dynamic module does not define module export function</code> at runtime.
360	</div>
361	
362	<!-- ─────────────────────────────────────────────── -->
363	<h2 id="findpython">5. PYBIND11_FINDPYTHON=ON and Why It Matters</h2>
364	
365	<p>CMake ships with two Python-finding modules:</p>
366	
367	<table>
368	  <tr><th>Module</th><th>CMake version</th><th>Status</th><th>Variables set</th></tr>
369	  <tr><td><code>FindPythonLibs</code></td><td>CMake &lt; 3.12</td><td>Deprecated</td><td><code>PYTHON_INCLUDE_DIRS</code>, <code>PYTHON_LIBRARIES</code></td></tr>
370	  <tr><td><code>FindPython3</code> / <code>FindPython</code></td><td>CMake &ge; 3.12</td><td>Current</td><td>Imported target <code>Python3::Python</code></td></tr>
371	</table>
372	
373	<p>The legacy <code>FindPythonLibs</code> searches system paths like <code>/usr/include/python3.x</code> and links against the system Python. This breaks in two common situations:</p>
374	
375	<ul>
376	  <li><strong>Virtual environments.</strong> The venv Python might be at <code>/home/user/.venv/bin/python</code> but the headers are only at <code>/home/user/.venv/include/python3.12</code>. CMake doesn't know to look there.</li>
377	  <li><strong>uv-managed Pythons.</strong> These live under <code>~/.local/share/uv/python/</code> and have bundled headers that the system CMake search paths will never find.</li>
378	</ul>
379	
380	<p>With <code>PYBIND11_FINDPYTHON=ON</code>, pybind11 uses <code>FindPython3</code> instead. If you also pass <code>-DPython3_EXECUTABLE=/path/to/python</code> (as the build script does), CMake derives all header paths from that interpreter — it calls <code>sysconfig.get_path('include')</code> internally.</p>
381	
382	<div class="file-label">CMakeLists.txt (root) — the key line</div>
383	<pre><span class="fn">set</span>(PYBIND11_FINDPYTHON ON)   <span class="cmt"># must come BEFORE find_package(pybind11)</span></pre>
384	
385	<div class="file-label">pyproject.toml — passed through scikit-build-core</div>
386	<pre>[tool.scikit-build.cmake]
387	args = [<span class="str">"-DPYBIND11_FINDPYTHON=ON"</span>]</pre>
388	
389	<div class="callout good">
390	  <strong>Why the build script also passes -DPython3_EXECUTABLE</strong>
391	  The script calls <code>$PYTHON -c "import sysconfig; print(sysconfig.get_path('include'))"</code> to verify headers exist, then passes <code>-DPython3_EXECUTABLE=$PYTHON</code> to CMake. This ensures the compiled extension links against exactly the Python it will be imported by — critical when multiple Python versions coexist on a machine.
392	</div>
393	
394	<!-- ─────────────────────────────────────────────── -->
395	<h2 id="fetchcontent">6. FetchContent vs find_package</h2>
396	
397	<p>The root CMakeLists.txt uses a hybrid strategy: try <code>find_package</code> first, fall back to <code>FetchContent</code>.</p>
398	
399	<div class="diagram"><span class="hi">find_package(pybind11 CONFIG QUIET)</span>
400	         │
401	         ├── FOUND ──▶ Use pip-installed pybind11 cmake files
402	         │             Path comes from: python -c "import pybind11; print(pybind11.get_cmake_dir())"
403	         │             Advantage: instant, no network, version pinned by pip
404	         │
405	         └── NOT FOUND ──▶ <span class="lo">FetchContent_Declare + FetchContent_MakeAvailable</span>
406	                           Downloads pybind11 v2.13.6 from GitHub into _build/_deps/
407	                           Advantage: self-contained, works without pip install pybind11</div>
408	
409	<h3>FetchContent mechanics</h3>
410	<p><code>FetchContent_Declare</code> registers a dependency with a URL/tag but does not download it yet. <code>FetchContent_MakeAvailable</code> downloads, configures, and makes the targets available — all at CMake configure time (before compilation begins). The fetched source lives in <code>_build/_deps/pybind11-src/</code>.</p>
411	
412	<h3>Why prefer find_package when available</h3>
413	<p>If pybind11 is pip-installed (<code>pip install pybind11</code>), <code>find_package</code> resolves in milliseconds and avoids a network call. The <code>build_cpp.sh</code> script passes the cmake dir explicitly:</p>
414	
415	<div class="file-label">scripts/build_cpp.sh (excerpt)</div>
416	<pre>PYBIND11_CMAKE=$($PYTHON -c <span class="str">"import pybind11; print(pybind11.get_cmake_dir())"</span> <span class="num">2</span>/dev/null || <span class="kw">true</span>)
417	<span class="kw">if</span> [ -n <span class="str">"$PYBIND11_CMAKE"</span> ]; then
418	    CMAKE_EXTRA_ARGS+=(<span class="str">"-Dpybind11_DIR=$PYBIND11_CMAKE"</span>)
419	<span class="kw">fi</span></pre>
420	
421	<!-- ─────────────────────────────────────────────── -->
422	<h2 id="scikit-build">7. scikit-build-core as the Build Backend</h2>
423	
424	<p>Python packages declare how they should be built in <code>pyproject.toml</code>. The <code>[build-system]</code> table names the <em>build backend</em>. This project uses <strong>scikit-build-core</strong>, which is specifically designed for packages that contain CMake-built C/C++/Fortran extensions.</p>
425	
426	<div class="file-label">pyproject.toml</div>
427	<pre>[build-system]
428	requires = [<span class="str">"scikit-build-core>=0.9"</span>, <span class="str">"pybind11>=2.12"</span>]
429	build-backend = <span class="str">"scikit_build_core.build"</span>
430	
431	[project]
432	name = <span class="str">"oil_alpha"</span>
433	version = <span class="str">"0.1.0"</span>
434	requires-python = <span class="str">">=3.10"</span>
435	
436	[tool.scikit-build]
437	wheel.packages = [<span class="str">"src/oil_alpha"</span>]   <span class="cmt"># include Python source in wheel</span>
438	
439	[tool.scikit-build.cmake]
440	build-type = <span class="str">"Release"</span>
441	args = [<span class="str">"-DPYBIND11_FINDPYTHON=ON"</span>]</pre>
442	
443	<h3>What scikit-build-core does when you run pip install</h3>
444	<ol>
445	  <li>pip calls the build backend to build a wheel.</li>
446	  <li>scikit-build-core runs <code>cmake -S . -B _skbuild/...</code> with the correct Python interpreter (the one running pip).</li>
447	  <li>It builds the CMake targets in Release mode.</li>
448	  <li>It copies the <code>.so</code> file and the Python source packages (<code>src/oil_alpha</code>) into the wheel's directory structure.</li>
449	  <li>pip installs the wheel, placing <code>oil_volume_cpp.so</code> in <code>site-packages/</code> alongside the <code>oil_alpha</code> package.</li>
450	</ol>
451	
452	<h3>Why not setuptools + setup.py?</h3>
453	<p>The old approach used <code>setuptools.Extension</code> to compile C extensions. It called the compiler directly and had poor CMake support. scikit-build-core is the modern replacement: it is pure CMake, handles cross-compilation, and integrates with the PEP 517 build system abstraction.</p>
454	
455	<!-- ─────────────────────────────────────────────── -->
456	<h2 id="editable-install">8. The Editable Install Flow</h2>
457	
458	<p>For development you want changes to Python source to be reflected immediately without reinstalling. An <em>editable install</em> (<code>pip install -e .</code>) achieves this by placing a <code>.pth</code> file in <code>site-packages</code> that adds <code>src/</code> to <code>sys.path</code> — so Python imports straight from the repo.</p>
459	
460	<div class="diagram">Developer runs:  <span class="hi">pip install -e .</span>
461	                     │
462	                     ▼
463	         scikit-build-core builds C++ extension
464	         cmake -S . -B _skbuild_editable/...
465	         cmake --build ...
466	                     │
467	                     ▼
468	         <span class="lo">oil_volume_cpp.cpython-312-...so</span>  placed in src/oil_alpha/
469	                     │
470	         <span class="lo">oil_alpha.pth</span>  placed in site-packages/ → points to src/
471	                     │
472	                     ▼
473	         import oil_alpha      ← reads from src/oil_alpha/*.py  (live)
474	         import oil_volume_cpp ← loads src/oil_alpha/oil_volume_cpp*.so</div>
475	
476	<div class="callout warn">
477	  <strong>C++ changes require a rebuild</strong>
478	  Editable install only makes Python changes live. If you modify <code>bindings.cpp</code>, you must re-run <code>pip install -e .</code> or <code>./scripts/build_cpp.sh</code> to recompile and replace the <code>.so</code> file.
479	</div>
480	
481	<!-- ─────────────────────────────────────────────── -->
482	<h2 id="parity-test">9. The Parity Test Pattern</h2>
483	
484	<p>A <em>parity test</em> is a correctness test that compares a C++ result against an independent reference implementation — typically NumPy — and asserts they agree within floating-point tolerance. It serves two purposes:</p>
485	<ul>
486	  <li><strong>Correctness gate:</strong> catches logic bugs in the C++ implementation before they corrupt live trading signals.</li>
487	  <li><strong>Regression guard:</strong> if a future compiler upgrade or algorithm change silently alters numerics, CI catches it.</li>
488	</ul>
489	
490	<div class="file-label">tests/test_cpp_bridge.py</div>
491	<pre><span class="kw">def</span> <span class="fn">_numpy_rolling_mean</span>(values, window):
492	    <span class="kw">import</span> numpy <span class="kw">as</span> np
493	    arr = np.array(values, dtype=<span class="ty">float</span>)
494	    result = np.full(len(arr), np.nan)
495	    <span class="kw">for</span> i <span class="kw">in</span> range(window - <span class="num">1</span>, len(arr)):
496	        result[i] = arr[i - window + <span class="num">1</span> : i + <span class="num">1</span>].mean()
497	    <span class="kw">return</span> result.tolist()
498	
499	
500	<span class="kw">def</span> <span class="fn">test_rolling_mean_parity</span>(cpp_module):
501	    values = [<span class="num">1.0</span>, <span class="num">2.0</span>, <span class="num">3.0</span>, <span class="num">4.0</span>, <span class="num">5.0</span>, <span class="num">6.0</span>, <span class="num">7.0</span>, <span class="num">8.0</span>, <span class="num">9.0</span>, <span class="num">10.0</span>]
502	    window = <span class="num">3</span>
503	    cpp_result = cpp_module.rolling_mean(values, window)
504	    np_result  = _numpy_rolling_mean(values, window)
505	    <span class="kw">for</span> i, (c, n) <span class="kw">in</span> enumerate(zip(cpp_result, np_result)):
506	        <span class="kw">if</span> math.isnan(n):
507	            <span class="kw">assert</span> math.isnan(c), <span class="str">f"index {i}: expected NaN, got {c}"</span>
508	        <span class="kw">else</span>:
509	            <span class="kw">assert</span> abs(c - n) &lt; <span class="num">1e-9</span>, <span class="str">f"index {i}: C++={c}, NumPy={n}"</span></pre>
510	
511	<p>The tolerance <code>1e-9</code> is chosen deliberately: it is tight enough to catch logic errors but loose enough to tolerate different floating-point evaluation orders between C++ (which may use FMA instructions) and NumPy (which may evaluate in a different order). For integer-valued inputs the result is exact and could use <code>1e-12</code> — the test <code>test_rolling_mean_window_1</code> does exactly that.</p>
512	
513	<h3>The fixture pattern</h3>
514	<pre>@pytest.fixture(scope=<span class="str">"module"</span>)
515	<span class="kw">def</span> <span class="fn">cpp_module</span>():
516	    <span class="kw">try</span>:
517	        <span class="kw">import</span> oil_volume_cpp
518	        <span class="kw">return</span> oil_volume_cpp
519	    <span class="kw">except</span> ImportError:
520	        pytest.skip(<span class="str">"oil_volume_cpp extension not built — run `pip install -e .` first"</span>)</pre>
521	
522	<p>The fixture uses <code>pytest.skip</code> rather than <code>pytest.fail</code> so that the test suite can still run in a pure-Python CI environment where the C++ extension has not been compiled. This is the correct behaviour: a missing extension is a configuration problem, not a code bug.</p>
523	
